div.script:
(function() {
    function openModal() {
        document.getElementById('sensore-enlarge-modal').style.display = 'flex';
        document.body.style.overflow = 'hidden';
    }
    function closeModal() {
        document.getElementById('sensore-enlarge-modal').style.display = 'none';
        document.body.style.overflow = '';
    }
    document.addEventListener('DOMContentLoaded', function() {
        var btn = document.getElementById('sensore-enlarge-btn');
        if (btn) btn.addEventListener('click', function(e){ e.preventDefault(); openModal(); });
        var closeBtn = document.getElementById('sensore-modal-close');
        if (closeBtn) closeBtn.addEventListener('click', closeModal);
        var backdrop = document.getElementById('sensore-modal-backdrop');
        if (backdrop) backdrop.addEventListener('click', closeModal);
        document.addEventListener('keydown', function(e){ if(e.key==='Escape') closeModal(); });
    });
})();

(function() {
    function openModal() {
        var modal = document.getElementById('oxy-flex-enlarge-modal');
        if (modal) modal.style.display = 'flex';
        document.body.style.overflow = 'hidden';
    }
    function closeModal(e) {
        if (e) e.preventDefault();
        var modal = document.getElementById('oxy-flex-enlarge-modal');
        if (modal) modal.style.display = 'none';
        document.body.style.overflow = '';
    }
    document.addEventListener('DOMContentLoaded', function() {
        var btn = document.getElementById('oxy-flex-enlarge-btn');
        if (btn) btn.addEventListener('click', function(e){ e.preventDefault(); openModal(); });
        var closeBtn = document.getElementById('oxy-flex-modal-close');
        if (closeBtn) closeBtn.addEventListener('click', closeModal);
        var backdrop = document.getElementById('oxy-flex-modal-backdrop');
        if (backdrop) backdrop.addEventListener('click', closeModal);
        document.addEventListener('keydown', function(e){ if(e.key === 'Escape') closeModal(e); });
    });
})();
